  const ::flatbuffers::String *TAPE_ID() const {
    return GetPointer<const ::flatbuffers::String *>(VT_TAPE_ID);
  }
  /// Time system indicator as recorded.
  const ::flatbuffers::String *TIME_SYSTEM_INDICATOR() const {
    return GetPointer<const ::flatbuffers::String *>(VT_TIME_SYSTEM_INDICATOR);
  }
  /// Coordinate system indicator as recorded.
  int32_t COORDINATE_SYSTEM_INDICATOR() const {
    return GetField<int32_t>(VT_COORDINATE_SYSTEM_INDICATOR, 0);
  }
  /// Coverage start, ISO 8601.
  const ::flatbuffers::String *START_EPOCH() const {
    return GetPointer<const ::flatbuffers::String *>(VT_START_EPOCH);
  }
  /// Coverage stop, ISO 8601.
  const ::flatbuffers::String *STOP_EPOCH() const {
    return GetPointer<const ::flatbuffers::String *>(VT_STOP_EPOCH);
  }
