  NCDCode500HeaderBuilder builder_(_fbb);
  builder_.add_EPOCH_STEP_SECONDS(EPOCH_STEP_SECONDS);
  builder_.add_HEADER_WORDS(HEADER_WORDS);
  builder_.add_STOP_EPOCH(STOP_EPOCH);
