inline NCDT::NCDT(const NCDT &o)
      : FORMAT(o.FORMAT),
        PROVIDER_DEFINED_FORMAT_NAME(o.PROVIDER_DEFINED_FORMAT_NAME),
        FORMAT_VERSION(o.FORMAT_VERSION),
        PRODUCER(o.PRODUCER),
        CREATION_DATE(o.CREATION_DATE),
        ORIGINATOR(o.ORIGINATOR),
        INTERNAL_FILE_NAME(o.INTERNAL_FILE_NAME),
        COMMENT_AREA(o.COMMENT_AREA),
        NATIVE_FRAME_NAME(o.NATIVE_FRAME_NAME),
        NATIVE_FRAME_ID(o.NATIVE_FRAME_ID),
        NATIVE_TIME_SYSTEM(o.NATIVE_TIME_SYSTEM),
        SP3_HEADER((o.SP3_HEADER) ? new NCDSP3HeaderT(*o.SP3_HEADER) : nullptr),
        SCENARIO_CONTAINER((o.SCENARIO_CONTAINER) ? new NCDScenarioEpochContainerT(*o.SCENARIO_CONTAINER) : nullptr),
        CODE_500_HEADER((o.CODE_500_HEADER) ? new NCDCode500HeaderT(*o.CODE_500_HEADER) : nullptr),
        START_TIME(o.START_TIME),
        STOP_TIME(o.STOP_TIME),
        SOURCE_BYTE_LENGTH(o.SOURCE_BYTE_LENGTH),
        SOURCE_SHA256(o.SOURCE_SHA256),
        SOURCE_CID(o.SOURCE_CID) {
  SEGMENTS.reserve(o.SEGMENTS.size());
  for (const auto &SEGMENTS_ : o.SEGMENTS) { SEGMENTS.emplace_back((SEGMENTS_) ? new NCDSegmentDescriptorT(*SEGMENTS_) : nullptr); }
}

