inline const NCD *GetNCD(const void *buf) {
  return ::flatbuffers::GetRoot<NCD>(buf);
}

inline const NCD *GetSizePrefixedNCD(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<NCD>(buf);
}

inline const char *NCDIdentifier() {
  return "$NCD";
}

inline bool NCDBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, NCDIdentifier());
}

inline bool SizePrefixedNCDBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, NCDIdentifier(), true);
}

template <bool B = false>
inline bool VerifyNCDBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<NCD>(NCDIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedNCDBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<NCD>(NCDIdentifier());
}

inline void FinishNCDBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<NCD> root) {
  fbb.Finish(root, NCDIdentifier());
}

inline void FinishSizePrefixedNCDBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<NCD> root) {
  fbb.FinishSizePrefixed(root, NCDIdentifier());
}

inline std::unique_ptr<NCDT> UnPackNCD(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<NCDT>(GetNCD(buf)->UnPack(res));
}

inline std::unique_ptr<NCDT> UnPackSizePrefixedNCD(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<NCDT>(GetSizePrefixedNCD(buf)->UnPack(res));
}

